from pathlib import Path


def replace_once(path, old, new):
    p = Path(path)
    text = p.read_text()
    if text.count(old) != 1:
        raise SystemExit(f"anchor mismatch {path}: expected 1 got {text.count(old)}\nANCHOR:\n{old}")
    p.write_text(text.replace(old, new, 1))

